var lifecycle = (generationActive, placementActive, terminal, canAbort = generationActive) => ({
  generationActive,
  placementActive,
  terminal,
  canAbort,
  blocksRegeneration: generationActive || placementActive
});
var SLOT_LIFECYCLE = {
  "recovered-pending": lifecycle(false, false, false),
  preparing: lifecycle(true, false, false),
  queued: lifecycle(true, false, false),
  parsing: lifecycle(true, false, false),
  generating: lifecycle(true, false, false),
  previewing: lifecycle(true, false, false),
  "placement-pending": lifecycle(false, true, false, false),
  "placement-repair-needed": lifecycle(false, false, false),
  completed: lifecycle(false, false, true),
  "image-unavailable": lifecycle(false, false, true),
  failed: lifecycle(false, false, true),
  cancelled: lifecycle(false, false, true)
};
function isGenerationActiveStatus(status) {
  return SLOT_LIFECYCLE[status].generationActive;
}
function isSlotLifecycleActive(status) {
  const semantics = SLOT_LIFECYCLE[status];
  return semantics.generationActive || semantics.placementActive;
}
function canAbortSlotStatus(status) {
  return SLOT_LIFECYCLE[status].canAbort;
}

// src/boundedCache.ts
class BoundedLruCache {
  options;
  entries = new Map;
  totalBytes = 0;
  constructor(options) {
    this.options = options;
    if (!Number.isInteger(options.maxEntries) || options.maxEntries < 1)
      throw new Error("maxEntries must be a positive integer");
  }
  get size() {
    this.pruneExpired();
    return this.entries.size;
  }
  get byteSize() {
    this.pruneExpired();
    return this.totalBytes;
  }
  has(key) {
    return this.get(key) !== undefined;
  }
  get(key) {
    const entry = this.entries.get(key);
    if (!entry)
      return;
    if (this.isExpired(entry)) {
      this.remove(key, entry);
      return;
    }
    entry.touchedAt = Date.now();
    this.entries.delete(key);
    this.entries.set(key, entry);
    return entry.value;
  }
  set(key, value) {
    const now = Date.now();
    const previous = this.entries.get(key);
    if (previous)
      this.remove(key, previous);
    const bytes = Math.max(0, Math.floor(this.options.sizeOf?.(value, key) ?? 0));
    this.entries.set(key, { value, createdAt: now, touchedAt: now, bytes });
    this.totalBytes += bytes;
    this.prune(now);
    return this;
  }
  delete(key) {
    const entry = this.entries.get(key);
    if (!entry)
      return false;
    this.remove(key, entry);
    return true;
  }
  clear() {
    this.entries.clear();
    this.totalBytes = 0;
  }
  keys() {
    this.pruneExpired();
    return this.entries.keys();
  }
  deleteWhere(predicate) {
    let removed = 0;
    for (const [key, entry] of [...this.entries]) {
      if (!predicate(key, entry.value))
        continue;
      this.remove(key, entry);
      removed += 1;
    }
    return removed;
  }
  isExpired(entry, now = Date.now()) {
    return Boolean(this.options.ttlMs && now - entry.createdAt > this.options.ttlMs);
  }
  pruneExpired(now = Date.now()) {
    if (!this.options.ttlMs)
      return;
    for (const [key, entry] of [...this.entries])
      if (this.isExpired(entry, now))
        this.remove(key, entry);
  }
  prune(now = Date.now()) {
    this.pruneExpired(now);
    while (this.entries.size > this.options.maxEntries || this.options.maxBytes !== undefined && this.totalBytes > this.options.maxBytes) {
      const oldest = this.entries.entries().next().value;
      if (!oldest)
        break;
      this.remove(oldest[0], oldest[1]);
    }
  }
  remove(key, entry) {
    if (!this.entries.delete(key))
      return;
    this.totalBytes = Math.max(0, this.totalBytes - entry.bytes);
  }
}

