var RAW_NESTED_METADATA = /(?:^|\n)\s*(?:[-*]\s*)?(?:metadata|source|provenance|card|history|sidecar|lorebook|world\s*(?:info|lore))\s*:\s*(?:\{|\[|$)/im;
