var SCRIPT_IDS = {
  "cast-introduction": "reverie_npc_intro_images_v1",
  "character-dossier": "relay_shenanigans_dossier_images_sparkle_v1",
  "location-file": "relay_shenanigans_location_images_sparkle_v1"
};
function cleanText(value) {
  return String(value || "").replace(/<(?:npc|place)-media\b[^>]*>[\s\S]*?<\/(?:npc|place)-media>/gi, "").replace(/<image_request\b[\s\S]*?<\/image_request>/gi, "").replace(/<!--\s*reverie-relay:[\s\S]*?-->/gi, "").replace(/<[^>]+>/g, " ").replace(/\[(?:\/?[A-Za-z_][^\]]*)\]/g, " ").replace(/[ \t]+/g, " ").replace(/\s*\n\s*/g, `
`).trim();
}
function extractNarrativeLorebookRecord(source, kind, occurrence = 0) {
  const script = narrativeRegexScripts("sparkle-button").find((candidate) => candidate.script_id === SCRIPT_IDS[kind]);
  if (!script)
    return null;
  const flags = script.flags?.includes("g") ? script.flags : `${script.flags || ""}g`;
  const matches = Array.from(String(source || "").matchAll(new RegExp(script.find_regex, flags)));
  const match = matches[Math.max(0, Number.isFinite(Number(occurrence)) ? Number(occurrence) : 0)];
  const groups = match?.groups || {};
  if (!match)
    return null;
  if (kind === "cast-introduction") {
    const title2 = cleanText(groups.name);
    const sections = [
      ["Tier", groups.tier],
      ["Identity", groups.identity],
      ["Appearance", groups.appearance],
      ["Personality", groups.personality],
      ["History and Motivation", groups.history],
      ["Relationships", groups.relationships]
    ].map(([label, value]) => [label, cleanText(value)]).filter(([, value]) => value);
    if (!title2 || !sections.length)
      return null;
    return { title: title2, keys: [title2], content: `Cast Introduction: ${title2}

${sections.map(([label, value]) => `${label}: ${value}`).join(`
`)}` };
  }
  const title = cleanText(groups.visible);
  const body = cleanText(groups.body);
  if (!title || !body)
    return null;
  return { title, keys: [title], content: `${kind === "character-dossier" ? "Character Dossier" : "Location File"}: ${title}

${body}` };
}
async function listBooks(api, userId) {
  const books = [];
  let offset = 0;
  for (;; ) {
    const page = await api.world_books.list({ limit: 100, offset, userId });
    books.push(...page.data);
    offset += page.data.length;
    if (!page.data.length || offset >= page.total)
      return books;
  }
}
async function exportNarrativeLorebookRecord(input) {
  const { api, chat, record: record3, kind, messageId, swipeId, userId } = input;
  const occurrence = Math.max(0, Number.isFinite(Number(input.occurrence)) ? Number(input.occurrence) : 0);
  const books = await listBooks(api, userId);
  let book = books.find((candidate) => candidate.metadata?.reverie_relay_export_book === true && candidate.metadata?.reverie_relay_lorebook_chat_id === chat.id);
  let createdBook = false;
  let entryId = "";
  try {
    if (!book) {
      const createdAt = new Date().toISOString();
      book = await api.world_books.create({
        name: `Reverie Relay Stage Archive - ${chat.name || "Chat"}`,
        description: "Chat-bound Narrative Surface exports created by Reverie Relay.",
        metadata: { reverie_relay_lorebook_chat_id: chat.id, reverie_relay_created_at: createdAt, reverie_relay_export_book: true }
      }, userId);
      createdBook = true;
    }
    const entry = await api.world_books.entries.create(book.id, {
      key: record3.keys,
      content: record3.content,
      comment: `${kind === "character-dossier" ? "Character Dossier" : kind === "location-file" ? "Location File" : "Cast Introduction"} - ${record3.title}`,
      position: 4,
      selective: false,
      constant: false,
      disabled: false,
      extensions: {
        reverie_relay_export_entry: true,
        reverie_relay_lorebook_chat_id: chat.id,
        reverie_relay_surface_kind: kind,
        reverie_relay_surface_occurrence: occurrence,
        reverie_relay_source_message_id: messageId,
        reverie_relay_source_swipe_id: swipeId,
        reverie_relay_source_fingerprint: contentFingerprint(`${kind}
${record3.title}
${record3.content}`),
        reverie_relay_exported_title: record3.title,
        reverie_relay_exported_at: new Date().toISOString(),
        reverie_relay_version: input.relayVersion || "unknown",
        reverie_relay_schema_version: Number.isFinite(Number(input.schemaVersion)) ? Number(input.schemaVersion) : 1
      }
    }, userId);
    entryId = entry.id;
    const existingBindings = Array.isArray(chat.metadata?.chat_world_book_ids) ? chat.metadata.chat_world_book_ids.filter((value) => typeof value === "string" && Boolean(value)) : [];
    if (!existingBindings.includes(book.id)) {
      await api.chats.update(chat.id, { metadata: { ...chat.metadata || {}, chat_world_book_ids: [...existingBindings, book.id] } }, userId);
    }
    return { bookId: book.id, entryId, message: `Sent ${record3.title} to ${book.name}.` };
  } catch (error) {
    if (entryId)
      await api.world_books.entries.delete(entryId, userId).catch(() => false);
    if (createdBook && book?.id)
      await api.world_books.delete(book.id, userId).catch(() => false);
    throw error;
  }
}

