      if (activeOpportunityId && !state.proseIllustrator.opportunities[activeOpportunityId])
        delete state.proseIllustrator.activeOpportunityIdByChat[chatId];
      const activePlanId = state.proseIllustrator.activePlanIdByChat[chatId];
      if (activePlanId && !state.proseIllustrator.plans[activePlanId])
        delete state.proseIllustrator.activePlanIdByChat[chatId];
