      severity: summary.orphanedFound || summary.malformed ? "warning" : "info",
      stage: "swipe-deleted",
      eventType: "swipe_deleted",
      chatId,
      messageId,
      swipeId: deletedSwipeId,
      message: `Removed ${summary.deletedSwipeRemoved} deleted-swipe record${summary.deletedSwipeRemoved === 1 ? "" : "s"} and retained ${summary.orphanedFound} for review.`,
