        continue;
      const sourceMessage = byId.get(opportunity.messageId);
      const swipes = sourceMessage ? Array.isArray(sourceMessage.swipes) && sourceMessage.swipes.length ? sourceMessage.swipes : [sourceMessage.content] : [];
