async function runInstallationSelfTest(chatId, frontendBuildId, frontendLoadedAt, nativeSettingsAvailable, userId) {
  const checks = [];
  try {
    await spindle.userStorage.getJson(CONFIG_PATH, { fallback: {}, userId });
    checks.push(healthCheck("config-storage", "Configuration storage", "core", true, "ok"));
  } catch (error) {
    checks.push(healthCheck("config-storage", "Configuration storage", "core", false, String(error)));
  }
  try {
    await spindle.userStorage.getJson("state.json", { userId });
    checks.push(healthCheck("state-storage", "Relay state storage", "core", true, "available; no Relay Health Check file created"));
  } catch (error) {
    checks.push(healthCheck("state-storage", "Relay state storage", "core", false, String(error)));
  }
  const state = chatId ? await getState(chatId, userId) : emptyState();
  checks.push(healthCheck("state-list", "Relay state list", "core", true, `${Object.keys(state.slots).length} slots`));
  checks.push(healthCheck("active-chat", "Active chat", "optional", Boolean(chatId), chatId || "no active chat"));
  if (chatId) {
    try {
      await spindle.chats.get(chatId, userId);
      checks.push(healthCheck("active-chat-read", "Active chat read", "core", true, "ok"));
    } catch (error) {
      checks.push(healthCheck("active-chat-read", "Active chat read", "core", false, String(error)));
    }
    try {
      const messages = await spindle.chat.getMessages(chatId);
      checks.push(healthCheck("message-listing", "Message listing", "core", true, `${messages.length} messages`));
    } catch (error) {
      checks.push(healthCheck("message-listing", "Message listing", "core", false, String(error)));
    }
  }
  checks.push(healthCheck("native-settings", "Native settings snapshot", "optional", nativeSettingsAvailable === true, nativeSettingsAvailable ? "available" : "unavailable"));
  try {
    const connections = await spindle.imageGen.listConnections(userId);
    checks.push(healthCheck("imagegen-connection", "ImageGen connection", "optional", connections.length > 0, connections.length ? "connection available" : "no connection available"));
  } catch (error) {
    checks.push(healthCheck("imagegen-connection", "ImageGen connection", "optional", false, String(error)));
  }
  const buildMatch = !frontendBuildId || frontendBuildId === BUILD_ID;
  checks.push(healthCheck("build-match", "Frontend/backend build match", "core", buildMatch, buildMatch ? "match" : `frontend ${frontendBuildId}, backend ${BUILD_ID}`));
  const health = summarizeRelayHealth(checks);
  if (chatId) {
    await mutateState(chatId, userId, (current) => appendStateLog(current, { severity: health === "fail" ? "error" : health === "warn" ? "warning" : "info", stage: "relay-health-check", eventType: "relay_health_check", chatId, message: `Relay Health Check ${health === "pass" ? "passed" : health === "warn" ? "completed with warnings" : "failed core checks"}. No image generation was started.`, details: { checks, frontendLoadedAt, health } }));
  }
  spindle.sendToFrontend({ type: "self_test_result", checks, frontendBuildId: frontendBuildId || "", backend: backendBuildInfo(), buildMatch }, userId);
  if (chatId)
    await sendState(userId, chatId);
}
