async function handleAssetLibraryAction(payload, userId) {
  await mutateState(payload.chatId, userId, (state) => {
    const now = Date.now();
    const asset = payload.assetId ? state.assetLibrary.assets[payload.assetId] : undefined;
    if (payload.action !== "clear_compare" && !asset)
      throw new Error("Asset not found.");
    switch (payload.action) {
      case "favorite":
        asset.favorite = true;
        asset.updatedAt = now;
        break;
      case "unfavorite":
        asset.favorite = false;
        asset.updatedAt = now;
        break;
      case "mark_reference":
        asset.visualReference = true;
        asset.updatedAt = now;
        break;
      case "clear_reference":
        asset.visualReference = false;
        asset.updatedAt = now;
        break;
      case "tag": {
        const tag = cleanString(payload.tag);
        if (!tag)
          throw new Error("Tag cannot be empty.");
        asset.tags = [...new Set([...asset.tags || [], tag])];
        asset.updatedAt = now;
        break;
      }
      case "untag": {
        const tag = cleanString(payload.tag);
        asset.tags = (asset.tags || []).filter((item) => item !== tag);
        asset.updatedAt = now;
        break;
      }
      case "compare":
        if (!payload.assetId || !payload.otherAssetId || !state.assetLibrary.assets[payload.otherAssetId])
          throw new Error("Choose two assets to compare.");
        state.assetLibrary.compare = { leftAssetId: payload.assetId, rightAssetId: payload.otherAssetId };
        break;
      case "clear_compare":
        state.assetLibrary.compare = {};
        break;
    }
    state.assetLibrary.updatedAt = now;
    appendStateLog(state, {
      severity: "info",
      stage: "asset-library",
      eventType: `asset_${payload.action}`,
      chatId: payload.chatId,
      message: `Asset Library action: ${payload.action}.`,
      details: { assetId: payload.assetId, otherAssetId: payload.otherAssetId, tag: payload.tag }
    });
  });
  await sendState(userId, payload.chatId);
}
